      logic: () =>
        getRepository(BankCard).find(
          (bc: any) =>
            l({
              logic: () => bc.CardID === this.InputCard.CardID,
              description: "bc.CardID=InputCard.CardID",
            }).build().pass,
        ),
      description: "BankCard.allInstance()->any(bc|bc.CardID=InputCard.CardID)",
    }).build().pass;
    /*Definition End*/

